// src/screens/DashboardLayout.jsx
// SAME UI as original. userName now comes from AuthContext (real Django user).

import { useState } from "react";
import Icon from "../components/Icon";
import { homeBg, tabsBg } from "../assets/images";
import HomeScreen     from "./HomeScreen";
import LiveScreen     from "./LiveScreen";
import LogsScreen     from "./LogsScreen";
import SettingsScreen from "./SettingsScreen";
import { useAuth } from "../context/AuthContext";

const TABS = [
  { id: "home",     label: "Home",          icon: "home",     topbarSub: "Welcome back"                       },
  { id: "live",     label: "Live Feed",     icon: "video",    topbarSub: "Monitor your scarecrows in real-time" },
  { id: "logs",     label: "Activity Logs", icon: "logs",     topbarSub: "Device history and events"           },
  { id: "settings", label: "Settings",      icon: "settings", topbarSub: "Manage your account & preferences"   },
];

export default function DashboardLayout({ onLogout }) {
  const { user } = useAuth(); // get real username from Django
  const [activeTab, setActiveTab] = useState("home");

  const userName   = user?.username || user?.full_name || "Farm Owner";
  const currentTab = TABS.find((t) => t.id === activeTab);
  const initials   = userName.split(" ").map((n) => n[0]).join("").toUpperCase().slice(0, 2);
  const bgImage    = activeTab === "home" ? homeBg : tabsBg;

  function renderScreen() {
    switch (activeTab) {
      case "home":     return <HomeScreen />;
      case "live":     return <LiveScreen />;
      case "logs":     return <LogsScreen />;
      case "settings": return <SettingsScreen onLogout={onLogout} />;
      default:         return <HomeScreen />;
    }
  }

  return (
    <div className="dash-root">
      {/* ── Sidebar ── */}
      <nav className="sidebar">
        <div className="sidebar-logo">
          <div className="sidebar-logo-icon">🌾</div>
          <div className="sidebar-logo-text">Scare<span>Crow</span></div>
        </div>

        {TABS.map((tab) => (
          <div
            key={tab.id}
            className={`nav-item${activeTab === tab.id ? " active" : ""}`}
            onClick={() => setActiveTab(tab.id)}
          >
            <Icon name={tab.icon} size={20} color="currentColor" />
            <span>{tab.label}</span>
          </div>
        ))}

        <div className="sidebar-bottom">
          <div className="sidebar-user">
            <div className="sidebar-avatar">{initials}</div>
            <div>
              <div className="sidebar-user-name">{userName}</div>
              <div className="sidebar-user-role">Farm Owner</div>
            </div>
          </div>
          <button className="logout-btn" onClick={onLogout}>
            <Icon name="logout" size={18} color="currentColor" />
            <span>Log Out</span>
          </button>
        </div>
      </nav>

      {/* ── Main ── */}
      <main
        className="main"
        style={{
          backgroundImage: `url(${bgImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          backgroundAttachment: "fixed",
        }}
      >
        {/* Overlay */}
        <div style={{
          position: "fixed",
          top: 0, left: 240, right: 0, bottom: 0,
          background: "rgba(200, 230, 160, 0.18)",
          pointerEvents: "none",
          zIndex: 0,
        }} />

        {/* Topbar */}
        <div className="topbar">
          <div>
            <div className="topbar-title">{currentTab.label}</div>
            <div className="topbar-subtitle">
              {activeTab === "home"
                ? `Welcome back, ${userName}`
                : currentTab.topbarSub}
            </div>
          </div>
          <div className="topbar-right">
            {activeTab === "home"     && <button className="icon-btn" title="Add Device"><Icon name="plus"    size={20} color="#fff" /></button>}
            {activeTab === "live"     && <button className="icon-btn" title="Refresh">  <Icon name="refresh" size={18} color="#fff" /></button>}
            {activeTab === "logs"     && <button className="icon-btn" title="Filter">   <Icon name="filter"  size={18} color="#fff" /></button>}
          </div>
        </div>

        {/* Page Content */}
        <div className="page-content" key={activeTab}>
          {renderScreen()}
        </div>
      </main>
    </div>
  );
}
